from collections import Counter
def task_func(file_pointer):
    """
    Reads from a given file pointer to a JSON file, evaluates strings that represent 
    dictionaries to actual dictionaries, and counts the frequency of each key 
    across all dictionary entries in the JSON data.

    Args:
        file_pointer: An open file-like object containing JSON data. 
                      The JSON data is expected to be a list of dictionaries 
                      or strings that can be evaluated as dictionaries.

    Returns:
        collections.Counter: A Counter object representing the frequency of 
                             each key found in the dictionaries.
    """
    # Load the JSON data from the file pointer
    try:
        data = json.load(file_pointer)
    except (json.JSONDecodeError, ValueError):
        return Counter()

    # Ensure the data is a list as per the function assumptions
    if not isinstance(data, list):
        return Counter()

    key_counts = Counter()

    for item in data:
        actual_dict = None

        # If the item is a string, evaluate it to a dictionary
        if isinstance(item, str):
            try:
                evaluated = ast.literal_eval(item)
                if isinstance(evaluated, dict):
                    actual_dict = evaluated
            except (ValueError, SyntaxError):
                # If evaluation fails or is not a dict, skip this item
                continue
        # If the item is already a dictionary
        elif isinstance(item, dict):
            actual_dict = item

        # If we have a valid dictionary, update the key counts
        if actual_dict is not None:
            key_counts.update(actual_dict.keys())

    return key_counts

