    Count the total appearances of all keys in all JSON files in the specified directory 
    and return a dictionary with the keys from the JSON files as keys and their 
    respective counts as values.

    This function recursively traverses all JSON structures (dictionaries and lists) 
    found within .json files in the given directory to ensure every occurrence 
    of a key is counted.

    Args:
        directory_path (str): The path to the directory containing JSON files.

    Returns:
        dict: A dictionary where keys are the strings found as keys in the JSON 
              files and values are their total occurrence counts.
    """
    counts = collections.Counter()

    def extract_keys(data):
        """Recursively traverse JSON data to count keys."""
        if isinstance(data, dict):
            for key, value in data.items():
                counts[key] += 1
                extract_keys(value)
        elif isinstance(data, list):
            for item in data:
                extract_keys(item)

    # Check if directory exists to avoid errors
    if not os.path.isdir(directory_path):
        return {}

    # Iterate through files in the directory
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
