from glob import glob
def task_func(directory, string):
    """
    Recursively searches for a specific string within the keys and values of JSON files
    in a given directory and its subdirectories.

    Args:
        directory (str): The directory to search within.
        string (str): The target string to search for (case-sensitive).

    Returns:
        list: A list of file paths (str) containing the string within their JSON data.
    """
    def search_in_json(data, target):
        """Helper function to recursively search for a string in JSON-like data."""
        if isinstance(data, dict):
            for k, v in data.items():
                if k == target:
                    return True
                if search_in_json(v, target):
                    return True
        elif isinstance(data, list):
            for item in data:
                if search_in_json(item, target):
                    return True
        elif isinstance(data, str):
            return data == target
        return False

    # Find all .json files recursively
    search_pattern = os.path.join(directory, '**', '*.json')
    json_files = glob(search_pattern, recursive=True)

    matching_files = []

    for file_path in json_files:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
                if search_in_json(data, string):
                    matching_files.append(file_path)
        except (json.JSONDecodeError, IOError, UnicodeDecodeError):
            # Skip files that aren't valid JSON or can't be read
            continue

    return matching_files

