from collections import defaultdict
def task_func(input_file="data.json"):
    """
    Reads a list of dictionaries from a JSON file, calculates the mean and median 
    for each key (ignoring non-numeric or missing values), and converts the 
    results into a sorted Pandas DataFrame.

    Args:
        input_file (str): Path to the JSON file.

    Returns:
        df (pd.DataFrame): A DataFrame indexed and sorted by the variable names, 
                           containing columns 'mean' and 'median'.
    """
    # Load the JSON data
    try:
        with open(input_file, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        # Return an empty DataFrame with the specified columns if file is missing or invalid
        return pd.DataFrame(columns=['mean', 'median'])

    # Ensure data is a list
    if not isinstance(data, list):
        return pd.DataFrame(columns=['mean', 'median'])

    # Group numeric values by key
    # defaultdict(list) allows us to append values to keys as we find them
    values_by_key = defaultdict(list)
    for entry in data:
        if not isinstance(entry, dict):
            continue
        for key, value in entry.items():
            # Check if value is numeric (int or float) and not a boolean 
            # (since bool is a subclass of int in Python)
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                # Check for NaN values which might be present in float types
                if not np.isnan(value):
                    values_by_key[key].append(value)

    # Calculate statistics for each key
    results = {}
    for key, values in values_by_key.items():
        if values:
            results[key] = {
                'mean': np.mean(values),
                'median': np.median(values)
            }

    # Handle the case where no numeric data was found
    if not results:
        return pd.DataFrame(columns=['mean', 'median'])

    # Convert results dictionary to a DataFrame
    # orient='index' makes the dictionary keys the DataFrame index
    df = pd.DataFrame.from_dict(results, orient='index')

    # Ensure columns are in the correct order
    df = df[['mean', 'median']]

    # Sort the index (variable names) alphabetically
    df.sort_index(inplace=True)

    return df

