import csv
def task_func(input_file, output_file):
    """
    Reads a list of dictionaries from a JSON file, calculates the mean and median 
    for each numeric field, and writes the results to a CSV file.

    Args:
        input_file (str): Path to the input JSON file.
        output_file (str): Path to the output CSV file.

    Returns:
        dict: A dictionary where each key is a field from the input JSON and 
              each value is another dictionary with the 'mean' and 'median' of that field.
    """
    # Read the JSON data
    try:
        with open(input_file, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

    if not isinstance(data, list) or not data:
        return {}

    # Collect numeric values for each key
    field_values = defaultdict(list)
    for entry in data:
        for key, value in entry.items():
            # Only process numeric values (int or float)
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                field_values[key].append(value)

    results = {}

    # Calculate statistics for each field that contains numeric data
    for key, values in field_values.items():
        if values:
            results[key] = {
                'mean': float(np.mean(values)),
                'median': float(np.median(values))
            }

    # Write the results to a CSV file
    if results:
        with open(output_file, 'w', newline='') as csvfile:
            fieldnames = ['Field', 'Mean', 'Median']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

            writer.writeheader()
            for key, stats in results.items():
                writer.writerow({
                    'Field': key,
                    'Mean': stats['mean'],
                    'Median': stats['median']
                })

    return results

