def task_func(input_file, output_file):
    """
    Reads a list of dictionaries from a JSON file, calculates the mean and median 
    for each numeric field, saves the results to a CSV file, and returns the stats.

    Args:
        input_file (str): Path to the input JSON file.
        output_file (str): Path to the output CSV file.

    Returns:
        dict: A dictionary where each key is a field name and the value is a 
              dictionary containing 'mean' and 'median'.
    """
    # Read the JSON data
    try:
        with open(input_file, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

    if not isinstance(data, list) or not data:
        return {}

    # Group numeric values by key
    values_by_key = defaultdict(list)
    for entry in data:
        if not isinstance(entry, dict):
            continue
        for key, value in entry.items():
            # Only process numeric values
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                values_by_key[key].append(value)

    # Calculate statistics
    results = {}
    for key, values in values_by_key.items():
        if values:
            mean_val = np.mean(values)
            median_val = np.median(values)
            # Convert numpy types to native Python floats for JSON/dictionary compatibility
            results[key] = {
                "mean": float(mean_val),
                "median": float(median_val)
            }

    # Write to CSV
    if results:
        with open(output_file, 'w', newline='') as f:
            fieldnames = ['field', 'mean', 'median']
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()
            for key, stats in results.items():
                writer.writerow({
                    'field': key,
                    'mean': stats['mean'],
                    'median': stats['median']
                })
    else:
        # Create an empty CSV with headers if no numeric data found
        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['field', 'mean', 'median'])

    return results
